);
INSERT INTO "UpdateLog" ("id","version","title","category","content","isCurrent","isLatest","createdAt","createdBy") VALUES('update_001','v2.1.20260729','全平台管理后台重构','新增','[{"title":"全新控制台","items":["新增全平台统计卡片，展示用户、订单、收入、排盘、供奉、积分等核心数据","最近7天订单和收入趋势图表","会员等级和排盘类型分布可视化"]},{"title":"排盘记录管理","items":["八字/紫微/奇门/梅花四种排盘记录统一管理","支持按类型和时间范围筛选"]},{"title":"支付记录管理","items":["全平台支付流水查看","支持状态筛选和时间范围筛选"]},{"title":"会员套餐配置","items":["会员套餐创建/编辑/上下架","价格和时长配置"]},{"title":"审计日志","items":["操作日志记录和查询","支持按操作类型、状态、日期筛选"]}]',1,1,'2026-07-29T10:00:00Z',NULL);
INSERT INTO "UpdateLog" ("id","version","title","category","content","isCurrent","isLatest","createdAt","createdBy") VALUES('update_002','v2.0.20260715','代理商功能完善','改进','[{"title":"代理商后台","items":["代理商独立后台，查看经营数据","客户管理和订单查看"]},{"title":"权限体系","items":["管理员/代理商/用户三级权限体系完善","角色隔离实现"]}]',0,0,'2026-07-15T10:00:00Z',NULL);
INSERT INTO "UpdateLog" ("id","version","title","category","content","isCurrent","isLatest","createdAt","createdBy") VALUES('update_003','v1.9.20260701','支付系统升级','改进','[{"title":"微信支付接入","items":["微信支付接口对接","Mock支付转正式支付"]},{"title":"订单管理","items":["订单状态流转优化","退款流程完善"]}]',0,0,'2026-07-01T10:00:00Z',NULL);
